import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const drnSchema = z.object({
  date: z.string().min(1, "Date is required"),
  doc_type: z.string().min(1, "Document type is required"),
  associated_project_id: z.string().optional().nullable(),
  associated_token_id: z.string().optional().nullable(),
  document_nature: z.string().min(1, "Document nature is required"),
  intended_user: z.string().min(1, "Intended user is required"),
  description: z.string().min(1, "Description is required"),
  revision: z.string().min(1, "Revision is required"),
  status: z.string().min(1, "Status is required"),
  remarks: z.string().optional().nullable(),
});

type DRNFormData = z.infer<typeof drnSchema>;

interface DRNFormProps {
  initialData?: Partial<DRNFormData>;
  onSubmit: (data: DRNFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function DRNForm({ initialData, onSubmit, onCancel, isLoading }: DRNFormProps) {
  const form = useForm<DRNFormData>({
    resolver: zodResolver(drnSchema),
    defaultValues: {
      date: initialData?.date ?? "",
      doc_type: initialData?.doc_type ?? "",
      associated_project_id: initialData?.associated_project_id ?? null,
      associated_token_id: initialData?.associated_token_id ?? null,
      document_nature: initialData?.document_nature ?? "",
      intended_user: initialData?.intended_user ?? "",
      description: initialData?.description ?? "",
      revision: initialData?.revision ?? "R0",
      status: initialData?.status ?? "draft",
      remarks: initialData?.remarks ?? null,
    },
  });

  const { data: projectsData } = useQuery({
    queryKey: ["projects-for-drn"],
    queryFn: () => api.listProjects({ page_size: 200 }),
  });

  const { data: tokensData } = useQuery({
    queryKey: ["tokens-for-drn"],
    queryFn: () => api.listTokens({ page_size: 200 }),
  });

  const projects = projectsData?.items ?? [];
  const tokens = tokensData?.items ?? [];

  const handleSubmit = async (data: DRNFormData) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await onSubmit(data as any);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Document Release Note</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="date">Date *</Label>
              <Input id="date" type="date" {...form.register("date")} />
              {form.formState.errors.date && (
                <p className="text-sm text-red-500">{form.formState.errors.date.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="doc_type">Document Type *</Label>
              <Select
                value={form.watch("doc_type")}
                onValueChange={(val) => form.setValue("doc_type", val)}
              >
                <SelectTrigger id="doc_type">
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="CON">CON</SelectItem>
                  <SelectItem value="DBR">DBR</SelectItem>
                  <SelectItem value="CAS">CAS</SelectItem>
                  <SelectItem value="GAD">GAD</SelectItem>
                  <SelectItem value="KDR">KDR</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.doc_type && (
                <p className="text-sm text-red-500">{form.formState.errors.doc_type.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Associated Project</Label>
              <Select
                value={form.watch("associated_project_id") ?? ""}
                onValueChange={(val) => form.setValue("associated_project_id", val || null)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="None" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {projects.map((p) => (
                    <SelectItem key={p.id} value={p.id}>
                      {p.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Associated Token</Label>
              <Select
                value={form.watch("associated_token_id") ?? ""}
                onValueChange={(val) => form.setValue("associated_token_id", val || null)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="None" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  {tokens.map((t) => (
                    <SelectItem key={t.id} value={t.id}>
                      {t.token_code}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="document_nature">Document Nature *</Label>
              <Input id="document_nature" {...form.register("document_nature")} />
              {form.formState.errors.document_nature && (
                <p className="text-sm text-red-500">{form.formState.errors.document_nature.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="intended_user">Intended User *</Label>
              <Input id="intended_user" {...form.register("intended_user")} />
              {form.formState.errors.intended_user && (
                <p className="text-sm text-red-500">{form.formState.errors.intended_user.message as string}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description *</Label>
            <Textarea id="description" {...form.register("description")} />
            {form.formState.errors.description && (
              <p className="text-sm text-red-500">{form.formState.errors.description.message as string}</p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Revision *</Label>
              <Select
                value={form.watch("revision")}
                onValueChange={(val) => form.setValue("revision", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select revision" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="R0">R0</SelectItem>
                  <SelectItem value="R1">R1</SelectItem>
                  <SelectItem value="R2">R2</SelectItem>
                  <SelectItem value="R3">R3</SelectItem>
                  <SelectItem value="R4">R4</SelectItem>
                  <SelectItem value="R5">R5</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.revision && (
                <p className="text-sm text-red-500">{form.formState.errors.revision.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label>Status *</Label>
              <Select
                value={form.watch("status")}
                onValueChange={(val) => form.setValue("status", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="submitted">Submitted</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="rejected">Rejected</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.status && (
                <p className="text-sm text-red-500">{form.formState.errors.status.message as string}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="remarks">Remarks</Label>
            <Textarea id="remarks" {...form.register("remarks")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const timeLogSchema = z.object({
  log_date: z.string().min(1, "Log date is required"),
  employee_id: z.string().min(1, "Employee is required"),
  employee_role_at_log: z.string().min(1, "Employee role is required"),
  work_type: z.string().min(1, "Work type is required"),
  reference_id: z.string().min(1, "Reference ID is required"),
  reference_kind: z.string().min(1, "Reference kind is required"),
  revision: z.boolean().default(false),
  project_name: z.string().min(1, "Project name is required"),
  activity_type: z.string().min(1, "Activity type is required"),
  software_used: z.string().optional().default(""),
  work_mode: z.string().min(1, "Work mode is required"),
  hours_logged: z.number().min(0.5, "Minimum 0.5 hours").step(0.5),
  billable_hours: z.number().min(0, "Cannot be negative").step(0.5),
  remarks: z.string().optional().nullable(),
}).refine((data) => data.billable_hours <= data.hours_logged, {
  message: "Billable hours cannot exceed hours logged",
  path: ["billable_hours"],
});

type TimeLogFormData = z.infer<typeof timeLogSchema>;

interface TimeLogFormProps {
  initialData?: Partial<TimeLogFormData>;
  onSubmit: (data: TimeLogFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function TimeLogForm({ initialData, onSubmit, onCancel, isLoading }: TimeLogFormProps) {
  const form = useForm<TimeLogFormData>({
    resolver: zodResolver(timeLogSchema),
    defaultValues: {
      log_date: initialData?.log_date ?? "",
      employee_id: initialData?.employee_id ?? "",
      employee_role_at_log: initialData?.employee_role_at_log ?? "",
      work_type: initialData?.work_type ?? "",
      reference_id: initialData?.reference_id ?? "",
      reference_kind: initialData?.reference_kind ?? "project",
      revision: initialData?.revision ?? false,
      project_name: initialData?.project_name ?? "",
      activity_type: initialData?.activity_type ?? "",
      software_used: initialData?.software_used ?? "",
      work_mode: initialData?.work_mode ?? "office",
      hours_logged: initialData?.hours_logged ?? 0.5,
      billable_hours: initialData?.billable_hours ?? 0,
      remarks: initialData?.remarks ?? null,
    },
  });

  const { data: usersData } = useQuery({
    queryKey: ["users-for-time-log"],
    queryFn: () => api.listUsers({ page_size: 200 }),
  });

  const users = usersData?.items ?? [];

  const handleSubmit = async (data: TimeLogFormData) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await onSubmit(data as any);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Time Log Entry</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="log_date">Log Date *</Label>
              <Input id="log_date" type="date" {...form.register("log_date")} />
              {form.formState.errors.log_date && (
                <p className="text-sm text-red-500">{form.formState.errors.log_date.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label>Employee *</Label>
              <Select
                value={form.watch("employee_id")}
                onValueChange={(val) => form.setValue("employee_id", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select employee" />
                </SelectTrigger>
                <SelectContent>
                  {users.map((u) => (
                    <SelectItem key={u.id} value={u.id}>
                      {u.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {form.formState.errors.employee_id && (
                <p className="text-sm text-red-500">{form.formState.errors.employee_id.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="employee_role_at_log">Employee Role *</Label>
              <Input id="employee_role_at_log" {...form.register("employee_role_at_log")} />
              {form.formState.errors.employee_role_at_log && (
                <p className="text-sm text-red-500">{form.formState.errors.employee_role_at_log.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="work_type">Work Type *</Label>
              <Input id="work_type" placeholder="e.g. Design, Review" {...form.register("work_type")} />
              {form.formState.errors.work_type && (
                <p className="text-sm text-red-500">{form.formState.errors.work_type.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="reference_id">Reference ID *</Label>
              <Input id="reference_id" {...form.register("reference_id")} />
              {form.formState.errors.reference_id && (
                <p className="text-sm text-red-500">{form.formState.errors.reference_id.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label>Reference Kind *</Label>
              <Select
                value={form.watch("reference_kind")}
                onValueChange={(val) => form.setValue("reference_kind", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select kind" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="project">Project</SelectItem>
                  <SelectItem value="token">Token</SelectItem>
                  <SelectItem value="doc">Document</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.reference_kind && (
                <p className="text-sm text-red-500">{form.formState.errors.reference_kind.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="project_name">Project Name *</Label>
              <Input id="project_name" {...form.register("project_name")} />
              {form.formState.errors.project_name && (
                <p className="text-sm text-red-500">{form.formState.errors.project_name.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="activity_type">Activity Type *</Label>
              <Input id="activity_type" placeholder="e.g. Modeling, Drafting" {...form.register("activity_type")} />
              {form.formState.errors.activity_type && (
                <p className="text-sm text-red-500">{form.formState.errors.activity_type.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="software_used">Software Used</Label>
              <Input id="software_used" placeholder="e.g. AutoCAD, Revit" {...form.register("software_used")} />
            </div>
            <div className="space-y-2">
              <Label>Work Mode *</Label>
              <Select
                value={form.watch("work_mode")}
                onValueChange={(val) => form.setValue("work_mode", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select mode" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="office">Office</SelectItem>
                  <SelectItem value="remote">Remote</SelectItem>
                  <SelectItem value="hybrid">Hybrid</SelectItem>
                </SelectContent>
              </Select>
              {form.formState.errors.work_mode && (
                <p className="text-sm text-red-500">{form.formState.errors.work_mode.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="hours_logged">Hours Logged *</Label>
              <Input
                id="hours_logged"
                type="number"
                step="0.5"
                min="0.5"
                {...form.register("hours_logged", { valueAsNumber: true })}
              />
              {form.formState.errors.hours_logged && (
                <p className="text-sm text-red-500">{form.formState.errors.hours_logged.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="billable_hours">Billable Hours *</Label>
              <Input
                id="billable_hours"
                type="number"
                step="0.5"
                min="0"
                {...form.register("billable_hours", { valueAsNumber: true })}
              />
              {form.formState.errors.billable_hours && (
                <p className="text-sm text-red-500">{form.formState.errors.billable_hours.message as string}</p>
              )}
            </div>
            <div className="space-y-2 flex items-end pb-1">
              <label className="flex items-center gap-2 text-sm">
                <input
                  type="checkbox"
                  className="h-4 w-4 rounded border-gray-300"
                  checked={form.watch("revision")}
                  onChange={(e) => form.setValue("revision", e.target.checked)}
                />
                Revision
              </label>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="remarks">Remarks</Label>
            <Textarea id="remarks" {...form.register("remarks")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const sustainabilitySchema = z.object({
  reference_id: z.string().min(1, "Reference (project) is required"),
  compliant_with_green_standards: z.string().optional().nullable(),
  total_energy_saved_kwh: z.number().optional().nullable(),
  co2_emissions_avoided_tco2e: z.number().optional().nullable(),
  lifecycle_cost_savings_inr: z.number().optional().nullable(),
  insulation_efficiency_actual_over_expected: z.number().optional().nullable(),
  payback_period_months: z.number().optional().nullable(),
  measured_at: z.string().optional().nullable(),
  notes: z.string().optional().nullable(),
});

type SustainabilityFormData = z.infer<typeof sustainabilitySchema>;

interface SustainabilityFormProps {
  initialData?: Partial<SustainabilityFormData>;
  onSubmit: (data: SustainabilityFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function SustainabilityForm({ initialData, onSubmit, onCancel, isLoading }: SustainabilityFormProps) {
  const form = useForm<SustainabilityFormData>({
    resolver: zodResolver(sustainabilitySchema),
    defaultValues: {
      reference_id: initialData?.reference_id ?? "",
      compliant_with_green_standards: initialData?.compliant_with_green_standards ?? null,
      total_energy_saved_kwh: initialData?.total_energy_saved_kwh ?? null,
      co2_emissions_avoided_tco2e: initialData?.co2_emissions_avoided_tco2e ?? null,
      lifecycle_cost_savings_inr: initialData?.lifecycle_cost_savings_inr ?? null,
      insulation_efficiency_actual_over_expected: initialData?.insulation_efficiency_actual_over_expected ?? null,
      payback_period_months: initialData?.payback_period_months ?? null,
      measured_at: initialData?.measured_at ?? null,
      notes: initialData?.notes ?? null,
    },
  });

  const { data: projectsData } = useQuery({
    queryKey: ["projects-for-sustainability"],
    queryFn: () => api.listProjects({ page_size: 200 }),
  });

  const projects = projectsData?.items ?? [];

  const handleSubmit = async (data: SustainabilityFormData) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await onSubmit(data as any);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Sustainability Record</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Project (Reference) *</Label>
              <Select
                value={form.watch("reference_id")}
                onValueChange={(val) => form.setValue("reference_id", val)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select project" />
                </SelectTrigger>
                <SelectContent>
                  {projects.map((p) => (
                    <SelectItem key={p.id} value={p.id}>
                      {p.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {form.formState.errors.reference_id && (
                <p className="text-sm text-red-500">{form.formState.errors.reference_id.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label>Green Standards Compliance</Label>
              <Select
                value={form.watch("compliant_with_green_standards") ?? ""}
                onValueChange={(val) => form.setValue("compliant_with_green_standards", val || null)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="None" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">None</SelectItem>
                  <SelectItem value="NBC">NBC</SelectItem>
                  <SelectItem value="ECBC">ECBC</SelectItem>
                  <SelectItem value="IGBC">IGBC</SelectItem>
                  <SelectItem value="IS">IS</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="total_energy_saved_kwh">Total Energy Saved (kWh)</Label>
              <Input
                id="total_energy_saved_kwh"
                type="number"
                step="0.01"
                min="0"
                {...form.register("total_energy_saved_kwh", { valueAsNumber: true })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="co2_emissions_avoided_tco2e">CO₂ Emissions Avoided (tCO₂e)</Label>
              <Input
                id="co2_emissions_avoided_tco2e"
                type="number"
                step="0.01"
                min="0"
                {...form.register("co2_emissions_avoided_tco2e", { valueAsNumber: true })}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="lifecycle_cost_savings_inr">Lifecycle Cost Savings (INR)</Label>
              <Input
                id="lifecycle_cost_savings_inr"
                type="number"
                step="0.01"
                min="0"
                {...form.register("lifecycle_cost_savings_inr", { valueAsNumber: true })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="insulation_efficiency_actual_over_expected">Insulation Efficiency (Actual/Expected)</Label>
              <Input
                id="insulation_efficiency_actual_over_expected"
                type="number"
                step="0.01"
                min="0"
                {...form.register("insulation_efficiency_actual_over_expected", { valueAsNumber: true })}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="payback_period_months">Payback Period (Months)</Label>
              <Input
                id="payback_period_months"
                type="number"
                step="1"
                min="0"
                {...form.register("payback_period_months", { valueAsNumber: true })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="measured_at">Measured At</Label>
              <Input id="measured_at" type="datetime-local" {...form.register("measured_at")} />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

